"use client";

import React, { useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import HomeRoundedIcon from "@mui/icons-material/HomeRounded";
import CalendarMonthRoundedIcon from "@mui/icons-material/CalendarMonthRounded";
import PeopleAltRoundedIcon from "@mui/icons-material/PeopleAltRounded";
import MedicalServicesRoundedIcon from "@mui/icons-material/MedicalServicesRounded";
import LocalHospitalRoundedIcon from "@mui/icons-material/LocalHospitalRounded";
import MenuRoundedIcon from "@mui/icons-material/MenuRounded";
import CloseRoundedIcon from "@mui/icons-material/CloseRounded";

const navItems = [
  { label: "Home",         href: "/",             icon: HomeRoundedIcon },
  { label: "Appointments", href: "/appointments",  icon: CalendarMonthRoundedIcon },
  { label: "Patients",     href: "/patients",      icon: PeopleAltRoundedIcon },
  { label: "Doctors",      href: "/doctors",       icon: MedicalServicesRoundedIcon },
  { label: "Hospitals",    href: "/hospitals",     icon: LocalHospitalRoundedIcon },
];

const Sidebar = () => {
  const [isOpen, setIsOpen] = useState(false);
  const pathname = usePathname();

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

        .sidebar-root * {
          font-family: 'Plus Jakarta Sans', sans-serif;
          box-sizing: border-box;
        }

        .sidebar-panel {
          width: 260px;
          min-width: 260px;
          max-width: 260px;
          flex-shrink: 0;
          background: #ffffff;
          border-right: 1px solid #e2e8f0;
          height: 100vh;
          display: flex;
          flex-direction: column;
          position: sticky;
          top: 0;
          box-shadow: 4px 0 24px rgba(0,0,0,0.04);
          overflow: hidden;
        }

        .nav-link {
          position: relative;
          display: flex;
          align-items: center;
          gap: 12px;
          padding: 11px 16px;
          border-radius: 14px;
          font-size: 14px;
          font-weight: 500;
          color: #64748b;
          text-decoration: none;
          transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
          overflow: hidden;
          white-space: nowrap;
        }

        .nav-link::before {
          content: '';
          position: absolute;
          inset: 0;
          background: linear-gradient(135deg, #e0f2fe, #f0f9ff);
          border-radius: 14px;
          opacity: 0;
          transition: opacity 0.2s ease;
        }

        .nav-link:hover::before { opacity: 1; }

        .nav-link:hover {
          color: #0284c7;
          transform: translateX(3px);
        }

        .nav-link.active {
          background: linear-gradient(135deg, #0ea5e9, #0284c7);
          color: #fff;
          font-weight: 600;
          box-shadow: 0 4px 14px rgba(14, 165, 233, 0.35);
        }

        .nav-link.active::before { display: none; }

        .nav-link.active:hover {
          transform: translateX(3px);
          color: #fff;
        }

        .icon-wrap {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 34px;
          min-width: 34px;
          height: 34px;
          border-radius: 10px;
          background: #f1f5f9;
          flex-shrink: 0;
          transition: background 0.2s ease;
          position: relative;
          z-index: 1;
        }

        .nav-link:hover .icon-wrap { background: #bae6fd; }
        .nav-link.active .icon-wrap { background: rgba(255,255,255,0.2); }

        .nav-label {
          position: relative;
          z-index: 1;
          flex: 1;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        .active-dot {
          width: 6px;
          min-width: 6px;
          height: 6px;
          border-radius: 50%;
          background: rgba(255,255,255,0.7);
          position: relative;
          z-index: 1;
          flex-shrink: 0;
        }

        .logo-icon {
          width: 42px;
          min-width: 42px;
          height: 42px;
          border-radius: 14px;
          background: linear-gradient(135deg, #0ea5e9, #0369a1);
          display: flex;
          align-items: center;
          justify-content: center;
          box-shadow: 0 4px 12px rgba(14, 165, 233, 0.3);
          flex-shrink: 0;
        }

        .divider {
          height: 1px;
          background: linear-gradient(90deg, transparent, #e2e8f0, transparent);
          margin: 0 16px;
          flex-shrink: 0;
        }

        /* Mobile */
        @media (max-width: 1023px) {
          .sidebar-panel {
            position: fixed;
            top: 0;
            left: 0;
            z-index: 40;
            transform: translateX(-100%);
            transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
          }
          .sidebar-panel.open {
            transform: translateX(0);
          }
        }
      `}</style>

      {/* Sidebar */}
      <div className={`sidebar-root sidebar-panel ${isOpen ? "open" : ""}`}>

        {/* Logo */}
        <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "24px 20px 20px" }}>
          <div className="logo-icon">
            <LocalHospitalRoundedIcon style={{ fontSize: 22, color: "#fff" }} />
          </div>
          <div style={{ overflow: "hidden" }}>
            <p style={{ fontSize: 15, fontWeight: 700, color: "#0f172a", lineHeight: 1.2, whiteSpace: "nowrap" }}>
              Appointments
            </p>
            <p style={{ fontSize: 11, color: "#94a3b8", fontWeight: 500, marginTop: 2, whiteSpace: "nowrap" }}>
              Hospital System
            </p>
          </div>
        </div>

        <div className="divider" />

        {/* Nav */}
        <nav style={{ flex: 1, padding: "20px 12px", overflow: "hidden" }}>
          <p style={{
            fontSize: 10,
            fontWeight: 700,
            color: "#94a3b8",
            letterSpacing: "0.1em",
            textTransform: "uppercase",
            padding: "0 8px",
            marginBottom: 10,
            whiteSpace: "nowrap",
          }}>
            Main Menu
          </p>

          <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 4 }}>
            {navItems.map(({ label, href, icon: Icon }) => {
              const isActive = pathname === href;
              return (
                <li key={href}>
                  <Link
                    href={href}
                    onClick={() => setIsOpen(false)}
                    className={`nav-link ${isActive ? "active" : ""}`}
                  >
                    <span className="icon-wrap">
                      <Icon style={{ fontSize: 17 }} />
                    </span>
                    <span className="nav-label">{label}</span>
                    {isActive && <span className="active-dot" />}
                  </Link>
                </li>
              );
            })}
          </ul>
        </nav>

      </div>
    </>
  );
};

export default Sidebar;